/**
 * Overview page — first view after importing a repository.
 *
 * Shows real data only:
 *   - File count, language coverage, snapshot identity
 *   - Capability coverage bar (full/text-only/binary)
 *   - Entry-point suggestions (top .py/.ts/.js files by path)
 *   - Summaries integration slot (INTEGRATION_SLOT: summaries.context-panel)
 */

import { useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { IntegrationPlaceholder } from '../../components/slots/IntegrationPlaceholder'
import { useWorkspace } from '../../contexts/WorkspaceContext'
import { getCapabilities } from '../../services/v1/api'
import type { CapabilityReport } from '../../types/v1'

function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`
  return `${(n / (1024 * 1024)).toFixed(1)} MB`
}

export default function OverviewPage() {
  const { projectId = '', snapshotId = '' } = useParams<{ projectId: string; snapshotId: string }>()
  const navigate = useNavigate()
  const ws = useWorkspace()
  const [caps, setCaps] = useState<CapabilityReport | null>(null)
  const [capsLoading, setCapsLoading] = useState(false)

  useEffect(() => {
    if (!projectId || !snapshotId) return
    setCapsLoading(true)
    getCapabilities(projectId, snapshotId)
      .then(r => setCaps(r))
      .catch(() => setCaps(null))
      .finally(() => setCapsLoading(false))
  }, [projectId, snapshotId])

  const files = ws.files
  const snap = ws.snapshot

  // Language breakdown
  const langCounts = files.reduce<Record<string, number>>((acc, f) => {
    const lang = f.language === 'unknown' ? 'other' : f.language
    acc[lang] = (acc[lang] ?? 0) + 1
    return acc
  }, {})
  const topLangs = Object.entries(langCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)

  const totalSize = files.reduce((n, f) => n + f.size, 0)

  // Suggested entry points: files with indicative names
  const ENTRY_NAMES = ['main.py', 'app.py', 'index.ts', 'index.js', 'main.ts', 'server.py',
    'main.go', 'cmd/main.go', 'src/main.rs', 'Program.cs', 'app.ts', 'index.tsx']
  const entryPoints = files
    .filter(f => ENTRY_NAMES.some(name => f.path.endsWith(name) || f.name === name))
    .slice(0, 5)

  const sourceDisplayRef = snap?.source.resolved_commit
    ? `Commit ${snap.source.resolved_commit.slice(0, 12)}`
    : snap?.source.archive_digest
      ? `Archive ${snap.source.archive_digest.slice(0, 12)}`
      : 'Local archive'

  return (
    <div className="content-scroll">
      {/* ── Page header ── */}
      <div style={{ marginBottom: 24 }}>
        <p className="content-header__eyebrow" style={{ margin: '0 0 4px' }}>Overview</p>
        <h1 className="content-header__title" style={{ margin: 0, fontSize: 22 }}>
          {ws.projectName ?? 'Repository'}
        </h1>
        {snap && (
          <p style={{ margin: '6px 0 0', fontSize: 12, color: 'var(--grepo-text-secondary)' }}>
            {sourceDisplayRef} &middot; {new Date(snap.created_at).toLocaleString()}
          </p>
        )}
      </div>

      {/* ── Stats ── */}
      {ws.loading ? (
        <div style={{ display: 'flex', gap: 16 }}>
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="stat-card" style={{ flex: 1 }}>
              <div className="skeleton skeleton--text" />
              <div className="skeleton skeleton--text" style={{ width: '60%' }} />
            </div>
          ))}
        </div>
      ) : (
        <ul className="stat-grid" aria-label="Repository statistics">
          <li className="stat-card">
            <span className="stat-card__label">Files</span>
            <span className="stat-card__value">{files.length.toLocaleString()}</span>
            <span className="stat-card__sub">inventoried</span>
          </li>
          <li className="stat-card">
            <span className="stat-card__label">Languages</span>
            <span className="stat-card__value">{topLangs.length}</span>
            <span className="stat-card__sub">detected</span>
          </li>
          <li className="stat-card">
            <span className="stat-card__label">Total size</span>
            <span className="stat-card__value">{formatBytes(totalSize)}</span>
            <span className="stat-card__sub">extracted</span>
          </li>
          {caps && (
            <li className="stat-card">
              <span className="stat-card__label">Parsed</span>
              <span className="stat-card__value">{caps.parsed_count}</span>
              <span className="stat-card__sub">syntax-analyzed</span>
            </li>
          )}
        </ul>
      )}

      {/* ── Capability coverage ── */}
      {caps && (
        <div style={{ marginTop: 24, padding: '16px 20px', background: 'var(--grepo-surface)', border: '1px solid var(--grepo-line)', borderRadius: 12 }}>
          <p style={{ margin: '0 0 8px', fontSize: 11, fontWeight: 700, color: 'var(--grepo-text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
            Analysis coverage
          </p>
          <div className="coverage-bar" role="list" aria-label="Coverage breakdown">
            <div className="coverage-bar__item" role="listitem">
              <span className="coverage-bar__label">Syntax-parsed</span>
              <span className="coverage-bar__value">{caps.parsed_count}</span>
            </div>
            <div className="coverage-bar__item" role="listitem">
              <span className="coverage-bar__label">Text-only</span>
              <span className="coverage-bar__value">{caps.text_only_count}</span>
            </div>
            <div className="coverage-bar__item" role="listitem">
              <span className="coverage-bar__label">Binary</span>
              <span className="coverage-bar__value">{caps.binary_count}</span>
            </div>
            <div className="coverage-bar__item" role="listitem">
              <span className="coverage-bar__label">Excluded</span>
              <span className="coverage-bar__value">{caps.excluded_count}</span>
            </div>
          </div>
          {caps.limitations.map((lim, i) => (
            <p key={i} style={{ margin: '8px 0 0', fontSize: 11, color: 'var(--grepo-text-secondary)' }}>
              {lim}
            </p>
          ))}
        </div>
      )}

      {/* ── Language breakdown ── */}
      {topLangs.length > 0 && (
        <div style={{ marginTop: 24, padding: '16px 20px', background: 'var(--grepo-surface)', border: '1px solid var(--grepo-line)', borderRadius: 12 }}>
          <p style={{ margin: '0 0 12px', fontSize: 11, fontWeight: 700, color: 'var(--grepo-text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
            Languages
          </p>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {topLangs.map(([lang, count]) => (
              <span
                key={lang}
                className="cap-chip cap-chip--text"
                aria-label={`${lang}: ${count} files`}
              >
                {lang} <strong style={{ fontWeight: 700 }}>{count}</strong>
              </span>
            ))}
          </div>
        </div>
      )}

      {/* ── Entry points ── */}
      {entryPoints.length > 0 && (
        <div style={{ marginTop: 24 }}>
          <p style={{ margin: '0 0 10px', fontSize: 11, fontWeight: 700, color: 'var(--grepo-text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
            Suggested entry points
          </p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {entryPoints.map(f => (
              <button
                key={f.id}
                type="button"
                className="recent-item"
                onClick={() => {
                  ws.selectEntity({ entityId: `file:${f.path}`, kind: 'file', path: f.path, fileId: f.id })
                  navigate(`/p/${projectId}/s/${snapshotId}/map`)
                }}
                aria-label={`Open ${f.path} in map`}
              >
                <span className="recent-item__name" style={{ fontFamily: 'var(--grepo-font-mono)', fontWeight: 400 }}>
                  {f.path}
                </span>
                <span className="recent-item__meta">{f.language}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── Empty state ── */}
      {!ws.loading && files.length === 0 && (
        <div className="empty-state" style={{ marginTop: 48 }}>
          <div className="empty-state__icon" aria-hidden="true">🗂</div>
          <h2 className="empty-state__title">Empty repository</h2>
          <p className="empty-state__body">
            No files were found in this snapshot after applying exclusion rules.
          </p>
        </div>
      )}

      {/* ── Summaries integration slot ── */}
      {/* INTEGRATION_SLOT: summaries.context-panel */}
      <div style={{ marginTop: 32 }}>
        <IntegrationPlaceholder
          slotId="summaries.context-panel"
          title="AI File &amp; Folder Summaries"
          description="Integration slot: put the summaries feature here. Not connected yet. The repository map and source browser work independently."
          showDevDisclosure={false}
        />
      </div>
    </div>
  )
}

